def power_set(data: list) -> list:
    """ Returns the powerset of a given list.

    >>> power_set([1,2,3])
    [{1}, {2}, {3}, {1, 2}, {1, 3}, {2, 3}, {1, 2, 3}]
    """
    powerset = []

    def find_subset(data: list, prefix: list) -> None:
        powerset.append(prefix)

        for i in range(len(data)):
            find_subset(data[i + 1:], prefix + [data[i]])

    find_subset(data, [])

    return powerset

