def max_nested_level_of_parens(paren_string: str) -> int:
    """ Input is a string of nested parentheses.
    The purpose of this function is to count the level of nesting, i.e. 3 for ((())())

    Args:
        paren_string (str): string of nested parentheses

    Returns:
        int: Level of nesting. E.g. 3 for ((())())
    """
    stack = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) == 0:
                return 0
            if len(stack) == 1:
                return 1
            else:
                stack.pop()
    if len(stack) == 0:
        return 0
    else:
        return len(stack) + 1


