def is_balanced(inner_group: str) -> bool:
    """ Check if a group of parentheses is balanced"""
    open_counter = 0
    close_counter = 0
    for char in inner_group:
        if char == '(':
            open_counter += 1
        if char == ')':
            close_counter += 1
            if close_counter > open_counter:
                return False
    return close_counter == open_counter


